contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will take a deposit amount as input and then attempt withdrawAll.
    // msg.sender for calls to c will be this contract.
    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // Record c's observable before-values
        uint beforeContractBalance = address(c).balance;
        uint beforeCredit = c.credit(address(this));

        // Make a deposit to c of `amount`
        c.deposit{value: amount}();

        // After deposit, observable values should have increased accordingly
        uint afterDepositContractBalance = address(c).balance;
        uint afterDepositCredit = c.credit(address(this));

        // Basic consistency: both contract balance and credit must increase by amount
        // (this uses a require so that the main assert can focus on withdraw behavior)
        require(afterDepositContractBalance == beforeContractBalance + amount,
                "contract balance didn't increase by deposit amount");
        require(afterDepositCredit == beforeCredit + amount,
                "credit didn't increase by deposit amount");

        // Attempt withdrawAll and capture whether it reverted
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint finalContractBalance = address(c).balance;
        uint finalCredit = c.credit(address(this));

        // Assert the general rule:
        // If withdrawAll succeeded (not reverted) then the caller's credit must be zero
        // and the contract balance must have decreased by the credited amount observed just before withdraw.
        // If withdrawAll reverted then both the contract balance and the caller's credit remain as afterDeposit values.
        assert(
            (!reverted && finalCredit == 0 && finalContractBalance + (afterDepositCredit) == afterDepositContractBalance)
            ||
            (reverted && finalCredit == afterDepositCredit && finalContractBalance == afterDepositContractBalance)
        );
    }

    // Allow receiving ETH sent back by C during withdrawAll
    receive() external payable {}
}

