        // deposit some Ether into c on behalf of this test contract (msg.sender for c will be this contract)
        c.deposit{value: depositAmount}();

        // read observable state after deposit
        uint beforeCredit = c.credit(address(this));
        uint beforeCBalance = address(c).balance;
        uint beforeMyBalance = address(this).balance;

        // call withdrawAll and record whether it reverted
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read observable state after withdrawAll (or failed attempt)
        uint afterCredit = c.credit(address(this));
        uint afterCBalance = address(c).balance;
        uint afterMyBalance = address(this).balance;

        // General invariant to assert:
        // - withdrawAll cannot increase contract balance: afterCBalance <= beforeCBalance
        // - if withdrawAll returned (did not revert) then caller's recorded credit became zero
        // - if withdrawAll reverted then balances and credit did not increase compared to before (conservative observable requirement)
        assert(
            // contract balance never increased
            afterCBalance <= beforeCBalance
            && (
                // case: call returned successfully
                (!reverted && afterCredit == 0)
                ||
                // case: call reverted -> require that contract balance and credit are at most as large as before
                (reverted && afterCBalance <= beforeCBalance && afterCredit <= beforeCredit)
            )
        );
    }

    // receive to accept refunds if needed
    receive() external payable {}
