        c.deposit{value: depositAmount}();

        // observe contract and tester balances after deposit
        uint beforeCBalance = address(c).balance;
        uint beforeMyBalance = address(this).balance;

        // call withdrawAll and record whether it reverted
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe balances after the withdrawAll attempt
        uint afterCBalance = address(c).balance;
        uint afterMyBalance = address(this).balance;

        // General rule (single assert):
        // - If withdrawAll reverted, contract balance must not have decreased.
        // - If withdrawAll returned, then the tester's balance cannot have increased by more than depositAmount,
        //   and the contract's balance cannot have decreased by less than the observed increase in tester balance.
