        assert(
            (reverted && afterCBalance >= beforeCBalance)
            || (
                !reverted
                && afterMyBalance >= beforeMyBalance
                && (afterMyBalance - beforeMyBalance) <= depositAmount
                && (beforeCBalance - afterCBalance) >= (afterMyBalance - beforeMyBalance)
            )
        );
    }

    // accept Ether refunds if withdrawAll forwards Ether to this contract
    receive() external payable {}
