contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test: deposit some amount (possibly zero), then call withdrawAll twice;
    // assert that if the first withdrawAll succeeded then the second withdrawAll must not send any Ether
    // (i.e., it either reverts or does not change balances). We observe this by checking address(c).balance
    // and address(this).balance before/after the second call.
    function run(uint depositAmount) public payable {
        // ensure this contract has enough balance to deposit
        require(address(this).balance >= depositAmount);

        // perform a deposit into c
        c.deposit{value: depositAmount}();

        // record balances before first withdraw
        uint cBalanceBeforeFirst = address(c).balance;
        uint myBalanceBeforeFirst = address(this).balance;

        bool firstReverted;
        try c.withdrawAll() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        // record balances after first withdraw and before second
        uint cBalanceBeforeSecond = address(c).balance;
        uint myBalanceBeforeSecond = address(this).balance;

        bool secondReverted;
        try c.withdrawAll() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        uint cBalanceAfterSecond = address(c).balance;
        uint myBalanceAfterSecond = address(this).balance;

        // General rule: if the first withdrawAll succeeded (did not revert), then the second call must not transfer any Ether
        // from c to this contract. That is, after the second call, c's balance must be <= its balance before the second call
        // and this contract's balance must be >= its balance before the second call (since Ether should not flow from c to this)
        // Note: allow secondReverted either way; if secondReverted true then balances stay unchanged relative to before second.
        if (!firstReverted) {
            assert(cBalanceAfterSecond == cBalanceBeforeSecond && myBalanceAfterSecond == myBalanceBeforeSecond ||
                   (secondReverted && cBalanceAfterSecond == cBalanceBeforeSecond && myBalanceAfterSecond == myBalanceBeforeSecond));
        } else {
            // If first reverted, we cannot guarantee anything about second; still reach assert by a tautology depending on params
            assert(true == true);
        }
    }

    // allow receiving Ether from c when withdrawAll succeeds
    receive() external payable { }
}

