        }

        // observe after
        uint tester_balance_after = address(this).balance;
        uint c_balance_after = address(c).balance;

        // If call succeeded then exactly depositAmount moved from c to this tester (balances reflect that),
        // and a second immediate withdrawAll transfers nothing more (balances unchanged by the second call or it reverts).
        bool success_case = (!reverted
            && tester_balance_after == tester_balance_before_withdraw + depositAmount
            && c_balance_after + depositAmount == c_balance_before_withdraw);

        if (!reverted) {
            // attempt a second withdrawAll: it must not transfer additional Ether (either reverts or leaves balances unchanged)
            uint tester_bal_before_second = address(this).balance;
            uint c_bal_before_second = address(c).balance;
