            }
            uint tester_bal_after_second = address(this).balance;
            uint c_bal_after_second = address(c).balance;

            // second call either reverts (balances unchanged) or succeeds but transfers 0 (balances unchanged)
            bool second_ok = (reverted2 && tester_bal_after_second == tester_bal_before_second && c_bal_after_second == c_bal_before_second)
                || (!reverted2 && tester_bal_after_second == tester_bal_before_second && c_bal_after_second == c_bal_before_second);

            assert(success_case && second_ok);
        } else {
            // revert case: balances must be unchanged compared to immediately after deposit
            assert(reverted && tester_balance_after == tester_balance_before_withdraw && c_balance_after == c_balance_before_withdraw);
        }
    }

    // accept ETH when C sends during withdrawAll
    receive() external payable { }
