        uint before = address(c).balance;

        // Perform deposit from this contract to c
        c.deposit{value: depositAmount}();

        // Record contract balance immediately after deposit
        uint afterDeposit = address(c).balance;

        // Now call withdrawAll and capture whether it reverted
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the withdraw attempt, observe contract balance
        uint afterWithdraw = address(c).balance;

        // We cannot read private credit mapping directly. But we can infer remaining credit for this tester
        // by attempting a second withdraw: if it succeeds it transfers some remaining credit; if it reverts,
        // remaining credit is zero (because withdrawAll sets credit to zero on success) or withdraw reverts.
        // To safely probe without changing state when possible, we try a second withdraw and catch revert.
        bool secondReverted;
        uint beforeProbe = address(this).balance;
        try c.withdrawAll() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        uint afterProbe = address(this).balance;

        // Infer remaining credit as the Ether we received in the probe (if any)
        uint inferredRemainingCredit = 0;
        if (!secondReverted && afterProbe > beforeProbe) {
            inferredRemainingCredit = afterProbe - beforeProbe;
        } else {
            // If second call reverted or didn't transfer value, inferred remaining credit is 0
            inferredRemainingCredit = 0;
        }

        // The general invariant we assert is that no Ether is created or destroyed by the withdraw attempts:
        // afterDeposit == afterWithdraw + inferredRemainingCredit
        // i.e., whatever is still held by c plus the inferred remaining credit equals the post-deposit balance.
        // Use a non-trivial expression involving parameters and observed values.
        assert(afterDeposit == afterWithdraw + inferredRemainingCredit);
    }

